class FakeFormatter final:public EventNotificationFormatter
{public:EventNotificationFormatResult result=EventNotificationFormatResult::SUCCESS;size_t calls=0U;const Event* lastEvent=nullptr;uint8_t* output=nullptr;size_t capacity=0U;size_t configuredLength=3U;uint8_t bytes[NOTIFICATION_RUNTIME_MAX_PAYLOAD_LENGTH]={0x41U,0U,0x42U};EventNotificationFormatResult format(const Event& e,uint8_t* out,size_t cap,size_t& length)override{++calls;lastEvent=&e;output=out;capacity=cap;length=configuredLength;if(result==EventNotificationFormatResult::SUCCESS&&configuredLength<=cap)memcpy(out,bytes,configuredLength);return result;}};
class FakeNotificationSink final:public NotificationSink
{public:NotificationSinkResult sendResult=NotificationSinkResult::SUCCESS;size_t sendCalls=0U,updateCalls=0U,cancelCalls=0U;NotificationId id=0U;NotificationChannelId channel=0U;NotificationTimestamp createdAt=0U;NotificationTimestamp createdHistory[EVENT_QUEUE_CAPACITY]={};const char* target=nullptr;size_t targetLength=0U;const uint8_t* payload=nullptr;size_t payloadLength=0U;NotificationSinkResult sendNotification(const NotificationMessage& m,const NotificationChannelDescriptor& d)override{if(sendCalls<EVENT_QUEUE_CAPACITY)createdHistory[sendCalls]=m.createdAt();++sendCalls;id=m.notificationId();channel=d.channelId();createdAt=m.createdAt();target=m.target();targetLength=m.targetLength();payload=m.payload();payloadLength=m.payloadLength();return sendResult;}NotificationSinkResult updateNotificationSend(NotificationChannelId)override{++updateCalls;return NotificationSinkResult::SUCCESS;}NotificationSinkResult cancelNotificationSend(NotificationChannelId)override{++cancelCalls;return NotificationSinkResult::SUCCESS;}};
class FakeEventSink final:public EventSink
{public:EventPublishResult result=EventPublishResult::SUCCESS;size_t calls=0U;Event event{};EventPublishResult publish(const Event& e)override{++calls;event=e;return result;}};
class FakeNodeInboundSink final:public NodeMessageSink{public:NodeMessageSinkResult onNodeMessage(const NodeInboundMessage&)override{return NodeMessageSinkResult::ACCEPTED;}};
class FakeNodeOutboundSink final:public NodeOutboundSink{public:NodeOutboundSinkResult sendToNode(NodeMessageId,const NodeDescriptor&,const uint8_t*,size_t)override{return NodeOutboundSinkResult::SUCCESS;}NodeOutboundSinkResult updateNodeSend(NodeId)override{return NodeOutboundSinkResult::SUCCESS;}NodeOutboundSinkResult cancelNodeSend(NodeId)override{return NodeOutboundSinkResult::SUCCESS;}};
class FakeIds final:public RuntimeIntegrationEventIdProvider{public:EventId next=1U;size_t calls=0U;EventId nextEventId()override{++calls;EventId value=next++;if(next==0U)next=1U;return value;}};
class ReentrantBindingHandler final:public EventHandler
{public:explicit ReentrantBindingHandler(EventToNotificationDispatchBinding& binding):binding_(binding){}RuntimeIntegrationResult nestedResult=RuntimeIntegrationResult::SUCCESS;size_t calls=0U;EventHandleResult handle(const Event&)override{++calls;nestedResult=binding_.dispatchEvents(9999U);return EventHandleResult::IGNORED;}private:EventToNotificationDispatchBinding& binding_;};
class PublishingHandler final:public EventHandler
{public:PublishingHandler(EventSink& sink,const Event& event):sink_(sink),event_(event){}size_t calls=0U;EventPublishResult publishResult=EventPublishResult::INVALID_EVENT;EventHandleResult handle(const Event&)override{++calls;if(calls==1U)publishResult=sink_.publish(event_);return EventHandleResult::IGNORED;}private:EventSink& sink_;Event event_;};
class FailingHandler final:public EventHandler
{public:size_t calls=0U;EventHandleResult handle(const Event&)override{++calls;return EventHandleResult::FAILED;}};
class EventToNotificationAdapterTestAccess{public:static void setNext(EventToNotificationAdapter& a,NotificationId id){a.nextId_=id;}static void saturate(EventToNotificationAdapter& a){a.forwarded_=UINT32_MAX;a.ignored_=UINT32_MAX;a.failed_=UINT32_MAX;}static RuntimeIntegrationResult map(NotificationRuntimeResult r){return EventToNotificationAdapter::mapRuntimeResult(r);}};
class EventToNotificationDispatchBindingTestAccess{public:static RuntimeIntegrationResult combine(RuntimeIntegrationResult a,RuntimeIntegrationResult b){return EventToNotificationDispatchBinding::combineDispatchResults(a,b);}static RuntimeIntegrationResult combineThree(RuntimeIntegrationResult a,RuntimeIntegrationResult b,RuntimeIntegrationResult c){return combine(combine(a,b),c);}static uint8_t priority(RuntimeIntegrationResult r){return EventToNotificationDispatchBinding::dispatchPriority(r);}};
class NodeToEventAdapterTestAccess{public:static void saturate(NodeToEventAdapter& a){a.forwarded_=UINT32_MAX;a.ignored_=UINT32_MAX;a.failed_=UINT32_MAX;}};
class CommandToEventAdapterTestAccess{public:static void saturate(CommandToEventAdapter& a){a.forwarded_=UINT32_MAX;a.ignored_=UINT32_MAX;a.failed_=UINT32_MAX;}};

static void assertIntegration(RuntimeIntegrationResult e,RuntimeIntegrationResult a){TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(e),static_cast<uint8_t>(a));}
static Event makeEvent(EventType type=EventType::NODE_OFFLINE,EventSeverity severity=EventSeverity::ERROR,EventId id=1U){Event e;e.id=id;e.type=type;e.severity=severity;e.sourceType=EventSourceType::NODE;e.sourceId=7U;e.timestampMs=100U;return e;}
static CommandResult commandResult(ExecutionStatus status,CommandErrorCode error){CommandResult r;r.commandId=31U;r.requestId=41U;if(status==ExecutionStatus::REJECTED)r.transitionTo(status,10U,error);else if(status==ExecutionStatus::SUCCESS){r.transitionTo(ExecutionStatus::VALIDATING,1U);r.transitionTo(ExecutionStatus::ACCEPTED,2U);r.transitionTo(ExecutionStatus::EXECUTING,3U);r.transitionTo(status,4U,error);}else if(status==ExecutionStatus::FAILED){r.transitionTo(ExecutionStatus::VALIDATING,1U);r.transitionTo(ExecutionStatus::ACCEPTED,2U);r.transitionTo(ExecutionStatus::EXECUTING,3U);r.transitionTo(status,4U,error);}return r;}
static NodeAddress nodeAddress(const char* text){NodeAddress a;TEST_ASSERT_TRUE(a.set(text));return a;}

struct NotificationFixture
{FakeNotificationSink sink;NotificationRegistry channels;NotificationRuntime runtime;FakeFormatter formatter;EventNotificationRegistry mappings;EventToNotificationAdapter adapter;explicit NotificationFixture(bool beginRuntime=true,NotificationDuration ttlMs=100U):sink(),channels(),runtime(channels),formatter(),mappings(),adapter(mappings,formatter,runtime){channels.registerChannel(NotificationChannelDescriptor::create(1U,NotificationChannelType::GENERIC,true),sink);if(beginRuntime)runtime.begin();const char target[]={'a','p','p'};mappings.registerMapping(EventNotificationMapping::create(EventType::NODE_OFFLINE,EventSeverity::WARNING,1U,NotificationPriority::HIGH_PRIORITY,ttlMs,target,sizeof(target),true));adapter.begin();}};

void test_common_mapping_models_and_validation()
{const char target[]={'x','y'};TEST_ASSERT_FALSE(EventNotificationMapping{}.isValid());TEST_ASSERT_FALSE(EventNotificationMapping::create(EventType::NONE,EventSeverity::INFO,1U,NotificationPriority::NORMAL,1U,target,2U,true).isValid());TEST_ASSERT_FALSE(EventNotificationMapping::create(EventType::NODE_OFFLINE,EventSeverity::COUNT,1U,NotificationPriority::NORMAL,1U,target,2U,true).isValid());TEST_ASSERT_FALSE(EventNotificationMapping::create(EventType::NODE_OFFLINE,EventSeverity::INFO,0U,NotificationPriority::NORMAL,1U,target,2U,true).isValid());TEST_ASSERT_FALSE(EventNotificationMapping::create(EventType::NODE_OFFLINE,EventSeverity::INFO,1U,NotificationPriority::COUNT,1U,target,2U,true).isValid());TEST_ASSERT_FALSE(EventNotificationMapping::create(EventType::NODE_OFFLINE,EventSeverity::INFO,1U,NotificationPriority::NORMAL,0U,target,2U,true).isValid());TEST_ASSERT_FALSE(EventNotificationMapping::create(EventType::NODE_OFFLINE,EventSeverity::INFO,1U,NotificationPriority::NORMAL,1U,nullptr,2U,true).isValid());TEST_ASSERT_TRUE(EventNotificationMapping::create(EventType::NODE_OFFLINE,EventSeverity::INFO,1U,NotificationPriority::NORMAL,1U,target,2U,false).isValid());TEST_ASSERT_FALSE(NodeEventMapping{}.isValid());TEST_ASSERT_TRUE(NodeEventMapping::create(NodeEventSignal::ONLINE,EventType::NODE_ONLINE,EventSeverity::NOTICE,true).isValid());TEST_ASSERT_FALSE(CommandEventMapping{}.isValid());TEST_ASSERT_TRUE(CommandEventMapping::create(ExecutionStatus::FAILED,CommandErrorCode::HARDWARE_FAILURE,EventType::COMMAND_FAILED,EventSeverity::ERROR,true).isValid());}
void test_registries_atomic_duplicate_lock_and_target_ownership()
{char target[]={'a','b'};EventNotificationRegistry e;EventNotificationMapping m=EventNotificationMapping::create(EventType::NODE_OFFLINE,EventSeverity::WARNING,1U,NotificationPriority::NORMAL,10U,target,2U,true);assertIntegration(RuntimeIntegrationResult::SUCCESS,e.registerMapping(m));target[0]='z';TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>('a'),static_cast<uint8_t>(e.find(EventType::NODE_OFFLINE)->target()[0]));assertIntegration(RuntimeIntegrationResult::DUPLICATE_MAPPING,e.registerMapping(m));TEST_ASSERT_EQUAL_UINT32(1U,e.size());e.lock();assertIntegration(RuntimeIntegrationResult::REGISTRY_LOCKED,e.registerMapping(EventNotificationMapping{}));NodeEventRegistry n;assertIntegration(RuntimeIntegrationResult::INVALID_INPUT,n.registerMapping(NodeEventMapping{}));assertIntegration(RuntimeIntegrationResult::SUCCESS,n.registerMapping(NodeEventMapping::create(NodeEventSignal::OFFLINE,EventType::NODE_OFFLINE,EventSeverity::ERROR,true)));assertIntegration(RuntimeIntegrationResult::DUPLICATE_MAPPING,n.registerMapping(NodeEventMapping::create(NodeEventSignal::OFFLINE,EventType::NODE_OFFLINE,EventSeverity::ERROR,true)));CommandEventRegistry c;CommandEventMapping cm=CommandEventMapping::create(ExecutionStatus::SUCCESS,CommandErrorCode::NONE,EventType::COMMAND_EXECUTED,EventSeverity::INFO,true);assertIntegration(RuntimeIntegrationResult::SUCCESS,c.registerMapping(cm));c.lock();assertIntegration(RuntimeIntegrationResult::REGISTRY_LOCKED,c.registerMapping(cm));}
void test_event_notification_filter_formatter_id_and_payload()
{NotificationFixture f;Event invalid;assertIntegration(RuntimeIntegrationResult::INVALID_INPUT,f.adapter.onEvent(invalid,100U));TEST_ASSERT_EQUAL_UINT32(1U,f.adapter.nextNotificationId());assertIntegration(RuntimeIntegrationResult::IGNORED,f.adapter.onEvent(makeEvent(EventType::NODE_ONLINE),100U));assertIntegration(RuntimeIntegrationResult::FILTERED,f.adapter.onEvent(makeEvent(EventType::NODE_OFFLINE,EventSeverity::NOTICE),100U));TEST_ASSERT_EQUAL_UINT32(0U,f.formatter.calls);f.formatter.result=EventNotificationFormatResult::NO_CONTENT;assertIntegration(RuntimeIntegrationResult::IGNORED,f.adapter.onEvent(makeEvent(),100U));TEST_ASSERT_EQUAL_UINT32(1U,f.adapter.nextNotificationId());f.formatter.result=EventNotificationFormatResult::SUCCESS;assertIntegration(RuntimeIntegrationResult::SUCCESS,f.adapter.onEvent(makeEvent(),100U));TEST_ASSERT_EQUAL_UINT32(1U,f.sink.sendCalls);TEST_ASSERT_EQUAL_UINT32(1U,f.sink.id);TEST_ASSERT_EQUAL_UINT8_ARRAY(f.formatter.bytes,f.sink.payload,3U);TEST_ASSERT_EQUAL_UINT32(NOTIFICATION_RUNTIME_MAX_PAYLOAD_LENGTH,f.formatter.capacity);TEST_ASSERT_EQUAL_UINT32(2U,f.adapter.nextNotificationId());}
void test_event_notification_formatter_fail_closed_and_runtime_mapping()
{NotificationFixture f;f.formatter.result=EventNotificationFormatResult::BUFFER_TOO_SMALL;assertIntegration(RuntimeIntegrationResult::FAILED,f.adapter.onEvent(makeEvent(),100U));f.formatter.result=EventNotificationFormatResult::INVALID_EVENT;assertIntegration(RuntimeIntegrationResult::INVALID_INPUT,f.adapter.onEvent(makeEvent(),100U));f.formatter.result=static_cast<EventNotificationFormatResult>(255U);assertIntegration(RuntimeIntegrationResult::INTERNAL_ERROR,f.adapter.onEvent(makeEvent(),100U));TEST_ASSERT_EQUAL_UINT32(0U,f.sink.sendCalls);TEST_ASSERT_EQUAL_UINT32(1U,f.adapter.nextNotificationId());TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(RuntimeIntegrationResult::RETRY_LATER),static_cast<uint8_t>(EventToNotificationAdapterTestAccess::map(NotificationRuntimeResult::CHANNEL_BUSY)));TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(RuntimeIntegrationResult::FAILED),static_cast<uint8_t>(EventToNotificationAdapterTestAccess::map(NotificationRuntimeResult::CHANNEL_NOT_FOUND)));TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(RuntimeIntegrationResult::INTERNAL_ERROR),static_cast<uint8_t>(EventToNotificationAdapterTestAccess::map(static_cast<NotificationRuntimeResult>(255U))));}
void test_notification_results_id_wrap_busy_and_saturation()
{NotificationFixture f;f.sink.sendResult=NotificationSinkResult::ACCEPTED;EventToNotificationAdapterTestAccess::setNext(f.adapter,UINT32_MAX);assertIntegration(RuntimeIntegrationResult::ACCEPTED,f.adapter.onEvent(makeEvent(),100U));TEST_ASSERT_EQUAL_UINT32(UINT32_MAX,f.sink.id);TEST_ASSERT_EQUAL_UINT32(1U,f.adapter.nextNotificationId());assertIntegration(RuntimeIntegrationResult::RETRY_LATER,f.adapter.onEvent(makeEvent(),100U));TEST_ASSERT_EQUAL_UINT32(1U,f.sink.sendCalls);TEST_ASSERT_EQUAL_UINT32(2U,f.adapter.nextNotificationId());TEST_ASSERT_EQUAL_UINT32(1U,f.adapter.failedCount());EventToNotificationAdapterTestAccess::saturate(f.adapter);f.adapter.onEvent(makeEvent(EventType::NODE_ONLINE),100U);TEST_ASSERT_EQUAL_UINT32(UINT32_MAX,f.adapter.forwardedCount());TEST_ASSERT_EQUAL_UINT32(UINT32_MAX,f.adapter.ignoredCount());TEST_ASSERT_EQUAL_UINT32(UINT32_MAX,f.adapter.failedCount());}
void test_notification_id_consumption_for_attempts_and_not_pre_send_failures()
{{NotificationFixture f;f.sink.sendResult=NotificationSinkResult::RETRY_LATER;assertIntegration(RuntimeIntegrationResult::RETRY_LATER,f.adapter.onEvent(makeEvent(),100U));TEST_ASSERT_EQUAL_UINT32(2U,f.adapter.nextNotificationId());TEST_ASSERT_EQUAL_UINT32(1U,f.sink.sendCalls);} {NotificationFixture f;f.sink.sendResult=NotificationSinkResult::REJECTED;assertIntegration(RuntimeIntegrationResult::REJECTED,f.adapter.onEvent(makeEvent(),100U));TEST_ASSERT_EQUAL_UINT32(2U,f.adapter.nextNotificationId());TEST_ASSERT_EQUAL_UINT32(1U,f.sink.sendCalls);} {NotificationFixture f;EventToNotificationAdapterTestAccess::setNext(f.adapter,0U);assertIntegration(RuntimeIntegrationResult::INTERNAL_ERROR,f.adapter.onEvent(makeEvent(),100U));TEST_ASSERT_EQUAL_UINT32(0U,f.adapter.nextNotificationId());TEST_ASSERT_EQUAL_UINT32(0U,f.sink.sendCalls);} {NotificationFixture f;f.formatter.result=EventNotificationFormatResult::FAILED;assertIntegration(RuntimeIntegrationResult::FAILED,f.adapter.onEvent(makeEvent(),100U));TEST_ASSERT_EQUAL_UINT32(1U,f.adapter.nextNotificationId());f.formatter.result=EventNotificationFormatResult::SUCCESS;f.formatter.configuredLength=0U;assertIntegration(RuntimeIntegrationResult::IGNORED,f.adapter.onEvent(makeEvent(),100U));TEST_ASSERT_EQUAL_UINT32(1U,f.adapter.nextNotificationId());}}
void test_bridge_forwards_exact_event_and_explicit_dispatch_time()
{{NotificationFixture f;EventToNotificationBridge bridge(f.adapter);Event event=makeEvent();event.timestampMs=1000U;const NotificationTimestamp dispatchNow=1050U;assertIntegration(RuntimeIntegrationResult::SUCCESS,bridge.onEvent(event,dispatchNow));TEST_ASSERT_EQUAL_PTR(&event,f.formatter.lastEvent);TEST_ASSERT_EQUAL_UINT32(1000U,f.sink.createdAt);TEST_ASSERT_EQUAL_UINT32(1U,f.sink.sendCalls);} {NotificationFixture f;EventToNotificationBridge bridge(f.adapter);Event event=makeEvent();event.timestampMs=1000U;const NotificationTimestamp dispatchNow=5000U;assertIntegration(RuntimeIntegrationResult::FAILED,bridge.onEvent(event,dispatchNow));TEST_ASSERT_EQUAL_PTR(&event,f.formatter.lastEvent);TEST_ASSERT_EQUAL_UINT32(0U,f.sink.sendCalls);TEST_ASSERT_EQUAL_UINT32(2U,f.adapter.nextNotificationId());}}
void test_compatibility_handle_is_not_the_production_notification_path()
{NotificationFixture f;Event event=makeEvent();const uint32_t failedBefore=f.adapter.failedCount();const RuntimeIntegrationResult resultBefore=f.adapter.lastResult();TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(EventHandleResult::IGNORED),static_cast<uint8_t>(f.adapter.handle(event)));TEST_ASSERT_EQUAL_UINT32(0U,f.formatter.calls);TEST_ASSERT_EQUAL_UINT32(0U,f.sink.sendCalls);TEST_ASSERT_EQUAL_UINT32(1U,f.adapter.nextNotificationId());TEST_ASSERT_EQUAL_UINT32(failedBefore,f.adapter.failedCount());assertIntegration(resultBefore,f.adapter.lastResult());EventToNotificationBridge bridge(f.adapter);assertIntegration(RuntimeIntegrationResult::SUCCESS,bridge.onEvent(event,150U));TEST_ASSERT_EQUAL_UINT32(1U,f.formatter.calls);TEST_ASSERT_EQUAL_UINT32(1U,f.sink.sendCalls);}
void test_node_adapter_real_state_transitions_results_and_no_duplicates()
{NodeRuntimeRegistry nodes;nodes.registerNode(NodeDescriptor::create(7U,NodeType::CUSTOM,nodeAddress("n/7"),50U,true));FakeNodeInboundSink inbound;FakeNodeOutboundSink outbound;NodeRuntime runtime(nodes,inbound,outbound);runtime.begin(0U);NodeRuntimeState before=*runtime.state(7U);uint8_t p[]={1U};runtime.handleInbound(NodeInboundMessage::create(1U,7U,nodeAddress("n/7"),p,1U),10U);NodeRuntimeState online=*runtime.state(7U);FakeEventSink events;FakeIds ids;NodeEventRegistry mappings;mappings.registerMapping(NodeEventMapping::create(NodeEventSignal::ONLINE,EventType::NODE_ONLINE,EventSeverity::NOTICE,true));mappings.registerMapping(NodeEventMapping::create(NodeEventSignal::OFFLINE,EventType::NODE_OFFLINE,EventSeverity::ERROR,true));mappings.registerMapping(NodeEventMapping::create(NodeEventSignal::SINK_REJECTED,EventType::NODE_HEALTH_CHANGED,EventSeverity::ERROR,true));NodeToEventAdapter adapter(mappings,events,ids);assertIntegration(RuntimeIntegrationResult::NOT_INITIALIZED,adapter.onNodeStateChanged(before,online,10U));adapter.begin();assertIntegration(RuntimeIntegrationResult::SUCCESS,adapter.onNodeStateChanged(before,online,10U));TEST_ASSERT_EQUAL_UINT16(7U,events.event.sourceId);TEST_ASSERT_EQUAL_UINT16(static_cast<uint16_t>(EventType::NODE_ONLINE),static_cast<uint16_t>(events.event.type));assertIntegration(RuntimeIntegrationResult::NO_CHANGE,adapter.onNodeStateChanged(online,online,11U));TEST_ASSERT_EQUAL_UINT32(1U,events.calls);runtime.update(60U);NodeRuntimeState offline=*runtime.state(7U);assertIntegration(RuntimeIntegrationResult::SUCCESS,adapter.onNodeStateChanged(online,offline,60U));assertIntegration(RuntimeIntegrationResult::SUCCESS,adapter.onNodeResult(7U,NodeRuntimeResult::SINK_REJECTED,61U));assertIntegration(RuntimeIntegrationResult::INVALID_INPUT,adapter.onNodeResult(0U,NodeRuntimeResult::SUCCESS,62U));assertIntegration(RuntimeIntegrationResult::INVALID_INPUT,adapter.onNodeResult(7U,static_cast<NodeRuntimeResult>(255U),62U));}
void test_node_publish_mapping_disabled_queue_full_and_saturation()
{NodeEventRegistry mappings;mappings.registerMapping(NodeEventMapping::create(NodeEventSignal::SEND_SUCCESS,EventType::NODE_HEALTH_CHANGED,EventSeverity::INFO,true));mappings.registerMapping(NodeEventMapping::create(NodeEventSignal::INTERNAL_ERROR,EventType::NODE_HEALTH_CHANGED,EventSeverity::CRITICAL,false));FakeEventSink sink;FakeIds ids;NodeToEventAdapter adapter(mappings,sink,ids);adapter.begin();assertIntegration(RuntimeIntegrationResult::SUCCESS,adapter.onNodeResult(2U,NodeRuntimeResult::SUCCESS,1U));sink.result=EventPublishResult::QUEUE_FULL;assertIntegration(RuntimeIntegrationResult::RETRY_LATER,adapter.onNodeResult(2U,NodeRuntimeResult::SUCCESS,2U));assertIntegration(RuntimeIntegrationResult::MAPPING_DISABLED,adapter.onNodeResult(2U,NodeRuntimeResult::INTERNAL_ERROR,3U));assertIntegration(RuntimeIntegrationResult::IGNORED,adapter.onNodeResult(2U,NodeRuntimeResult::ACCEPTED,4U));TEST_ASSERT_EQUAL_UINT32(2U,sink.calls);NodeToEventAdapterTestAccess::saturate(adapter);adapter.onNodeResult(2U,NodeRuntimeResult::SUCCESS,5U);TEST_ASSERT_EQUAL_UINT32(UINT32_MAX,adapter.forwardedCount());}
void test_command_adapter_mapping_sensitive_policy_and_results()
{CommandEventRegistry mappings;mappings.registerMapping(CommandEventMapping::create(ExecutionStatus::SUCCESS,CommandErrorCode::NONE,EventType::COMMAND_EXECUTED,EventSeverity::INFO,true));mappings.registerMapping(CommandEventMapping::create(ExecutionStatus::REJECTED,CommandErrorCode::UNAUTHORIZED,EventType::COMMAND_REJECTED,EventSeverity::ERROR,true));mappings.registerMapping(CommandEventMapping::create(ExecutionStatus::FAILED,CommandErrorCode::HARDWARE_FAILURE,EventType::COMMAND_FAILED,EventSeverity::CRITICAL,false));FakeEventSink sink;FakeIds ids;CommandToEventAdapter adapter(mappings,sink,ids);assertIntegration(RuntimeIntegrationResult::NOT_INITIALIZED,adapter.onCommandResult(commandResult(ExecutionStatus::SUCCESS,CommandErrorCode::NONE),10U));adapter.begin();assertIntegration(RuntimeIntegrationResult::SUCCESS,adapter.onCommandResult(commandResult(ExecutionStatus::SUCCESS,CommandErrorCode::NONE),10U));TEST_ASSERT_EQUAL_UINT32(31U,sink.event.payload.value1);TEST_ASSERT_EQUAL_UINT32(41U,sink.event.correlationId);TEST_ASSERT_EQUAL_STRING("",sink.event.message);assertIntegration(RuntimeIntegrationResult::SUCCESS,adapter.onCommandResult(commandResult(ExecutionStatus::REJECTED,CommandErrorCode::UNAUTHORIZED),11U));assertIntegration(RuntimeIntegrationResult::MAPPING_DISABLED,adapter.onCommandResult(commandResult(ExecutionStatus::FAILED,CommandErrorCode::HARDWARE_FAILURE),12U));CommandResult invalid;assertIntegration(RuntimeIntegrationResult::INVALID_INPUT,adapter.onCommandResult(invalid,13U));sink.result=EventPublishResult::QUEUE_FULL;assertIntegration(RuntimeIntegrationResult::RETRY_LATER,adapter.onCommandResult(commandResult(ExecutionStatus::SUCCESS,CommandErrorCode::NONE),14U));TEST_ASSERT_EQUAL_UINT32(3U,sink.calls);}
void test_command_unknown_mapping_duplicate_publish_and_saturation()
{CommandEventRegistry mappings;mappings.registerMapping(CommandEventMapping::create(ExecutionStatus::SUCCESS,CommandErrorCode::NONE,EventType::COMMAND_EXECUTED,EventSeverity::INFO,true));FakeEventSink sink;FakeIds ids;CommandToEventAdapter adapter(mappings,sink,ids);adapter.begin();assertIntegration(RuntimeIntegrationResult::IGNORED,adapter.onCommandResult(commandResult(ExecutionStatus::REJECTED,CommandErrorCode::INVALID_COMMAND),1U));sink.result=EventPublishResult::DUPLICATE_EVENT;assertIntegration(RuntimeIntegrationResult::REJECTED,adapter.onCommandResult(commandResult(ExecutionStatus::SUCCESS,CommandErrorCode::NONE),2U));CommandToEventAdapterTestAccess::saturate(adapter);adapter.onCommandResult(commandResult(ExecutionStatus::SUCCESS,CommandErrorCode::NONE),3U);TEST_ASSERT_EQUAL_UINT32(UINT32_MAX,adapter.forwardedCount());TEST_ASSERT_EQUAL_UINT32(UINT32_MAX,adapter.ignoredCount());TEST_ASSERT_EQUAL_UINT32(UINT32_MAX,adapter.failedCount());}
void test_integration_node_to_event_to_notification()
{EventQueue queue;EventDispatcher dispatcher(queue);FakeIds ids;NodeEventRegistry nodeMappings;nodeMappings.registerMapping(NodeEventMapping::create(NodeEventSignal::OFFLINE,EventType::NODE_OFFLINE,EventSeverity::ERROR,true));NodeToEventAdapter node(nodeMappings,queue,ids);node.begin();NotificationFixture notification;EventToNotificationBridge bridge(notification.adapter);EventToNotificationDispatchBinding binding(queue,dispatcher,bridge);assertIntegration(RuntimeIntegrationResult::SUCCESS,binding.begin());assertIntegration(RuntimeIntegrationResult::SUCCESS,node.onNodeResult(7U,NodeRuntimeResult::TIMEOUT,100U));TEST_ASSERT_NOT_NULL(queue.peek());assertIntegration(RuntimeIntegrationResult::SUCCESS,binding.dispatchEvents(125U));TEST_ASSERT_TRUE(queue.empty());TEST_ASSERT_EQUAL_UINT32(1U,notification.sink.sendCalls);TEST_ASSERT_EQUAL_UINT32(100U,notification.sink.createdAt);}
void test_integration_command_failure_filter_disabled_and_busy()
{EventQueue queue;EventDispatcher dispatcher(queue);FakeIds ids;CommandEventRegistry commands;commands.registerMapping(CommandEventMapping::create(ExecutionStatus::FAILED,CommandErrorCode::HARDWARE_FAILURE,EventType::NODE_OFFLINE,EventSeverity::ERROR,true));CommandToEventAdapter command(commands,queue,ids);command.begin();NotificationFixture notification;EventToNotificationBridge bridge(notification.adapter);EventToNotificationDispatchBinding binding(queue,dispatcher,bridge);binding.begin();notification.sink.sendResult=NotificationSinkResult::ACCEPTED;assertIntegration(RuntimeIntegrationResult::SUCCESS,command.onCommandResult(commandResult(ExecutionStatus::FAILED,CommandErrorCode::HARDWARE_FAILURE),100U));const Event event=*queue.peek();assertIntegration(RuntimeIntegrationResult::SUCCESS,binding.dispatchEvents(110U));TEST_ASSERT_EQUAL_UINT32(1U,notification.sink.sendCalls);TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(EventPublishResult::SUCCESS),static_cast<uint8_t>(queue.publish(event)));assertIntegration(RuntimeIntegrationResult::FAILED,binding.dispatchEvents(120U));TEST_ASSERT_EQUAL_UINT32(1U,notification.sink.sendCalls);}

void test_dispatch_binding_end_to_end_explicit_now_and_ttl()
{{EventQueue queue;EventDispatcher dispatcher(queue);NotificationFixture f(true,10000U);EventToNotificationBridge bridge(f.adapter);EventToNotificationDispatchBinding binding(queue,dispatcher,bridge);assertIntegration(RuntimeIntegrationResult::SUCCESS,binding.begin());Event event=makeEvent();event.timestampMs=1000U;TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(EventPublishResult::SUCCESS),static_cast<uint8_t>(queue.publish(event)));assertIntegration(RuntimeIntegrationResult::SUCCESS,binding.dispatchEvents(5000U));TEST_ASSERT_EQUAL_UINT32(1000U,f.sink.createdAt);TEST_ASSERT_EQUAL_UINT32(1U,f.sink.sendCalls);TEST_ASSERT_EQUAL_UINT32(2U,f.adapter.nextNotificationId());}
 {EventQueue queue;EventDispatcher dispatcher(queue);NotificationFixture f(true,2000U);EventToNotificationBridge bridge(f.adapter);EventToNotificationDispatchBinding binding(queue,dispatcher,bridge);binding.begin();Event event=makeEvent();event.timestampMs=1000U;queue.publish(event);assertIntegration(RuntimeIntegrationResult::FAILED,binding.dispatchEvents(5000U));TEST_ASSERT_EQUAL_UINT32(0U,f.sink.sendCalls);TEST_ASSERT_EQUAL_UINT32(2U,f.adapter.nextNotificationId());}}

void test_dispatch_binding_multiple_events_share_cycle_time_and_clear_context()
{EventQueue queue;EventDispatcher dispatcher(queue);NotificationFixture f(true,10000U);EventToNotificationBridge bridge(f.adapter);EventToNotificationDispatchBinding binding(queue,dispatcher,bridge);EventRuntimeControllerPort port(binding);MainControllerDependencies dependencies;dependencies.set(port);dependencies.require(MainControllerComponent::EVENT);MainController controller(dependencies);TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(MainControllerResult::SUCCESS),static_cast<uint8_t>(controller.begin(0U)));Event a=makeEvent(EventType::NODE_OFFLINE,EventSeverity::ERROR,1U),b=makeEvent(EventType::NODE_OFFLINE,EventSeverity::ERROR,2U),c=makeEvent(EventType::NODE_OFFLINE,EventSeverity::ERROR,3U);a.timestampMs=1000U;b.timestampMs=2000U;c.timestampMs=3000U;queue.publish(a);queue.publish(b);queue.publish(c);TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(MainControllerResult::SUCCESS),static_cast<uint8_t>(controller.update(5000U)));TEST_ASSERT_EQUAL_UINT32(3U,f.sink.sendCalls);TEST_ASSERT_EQUAL_UINT32(1000U,f.sink.createdHistory[0]);TEST_ASSERT_EQUAL_UINT32(2000U,f.sink.createdHistory[1]);TEST_ASSERT_EQUAL_UINT32(3000U,f.sink.createdHistory[2]);TEST_ASSERT_FALSE(binding.isDispatching());Event next=makeEvent(EventType::NODE_OFFLINE,EventSeverity::ERROR,4U);next.timestampMs=1000U;queue.publish(next);TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(MainControllerResult::COMPONENT_FAILED),static_cast<uint8_t>(controller.update(15000U)));TEST_ASSERT_EQUAL_UINT32(3U,f.sink.sendCalls);TEST_ASSERT_FALSE(binding.isDispatching());}

void test_dispatch_binding_context_guards_and_nested_dispatch()
{EventQueue queue;EventDispatcher dispatcher(queue);NotificationFixture f(true,10000U);EventToNotificationBridge bridge(f.adapter);EventToNotificationDispatchBinding binding(queue,dispatcher,bridge);Event event=makeEvent();const uint32_t forwardedBefore=f.adapter.forwardedCount(),ignoredBefore=f.adapter.ignoredCount(),failedBefore=f.adapter.failedCount();TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(EventHandleResult::FAILED),static_cast<uint8_t>(binding.handle(event)));TEST_ASSERT_EQUAL_UINT32(1U,f.adapter.nextNotificationId());TEST_ASSERT_EQUAL_UINT32(forwardedBefore,f.adapter.forwardedCount());TEST_ASSERT_EQUAL_UINT32(ignoredBefore,f.adapter.ignoredCount());TEST_ASSERT_EQUAL_UINT32(failedBefore,f.adapter.failedCount());assertIntegration(RuntimeIntegrationResult::NOT_INITIALIZED,binding.beginDispatch(1U));assertIntegration(RuntimeIntegrationResult::SUCCESS,binding.begin());assertIntegration(RuntimeIntegrationResult::SUCCESS,binding.beginDispatch(5000U));assertIntegration(RuntimeIntegrationResult::REJECTED,binding.beginDispatch(6000U));assertIntegration(RuntimeIntegrationResult::SUCCESS,binding.endDispatch());assertIntegration(RuntimeIntegrationResult::INVALID_ARGUMENT,binding.endDispatch());TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(EventHandleResult::FAILED),static_cast<uint8_t>(binding.handle(event)));ReentrantBindingHandler nested(binding);TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(EventHandlerRegistrationResult::SUCCESS),static_cast<uint8_t>(dispatcher.addHandler(nested)));queue.publish(event);assertIntegration(RuntimeIntegrationResult::SUCCESS,binding.dispatchEvents(5000U));assertIntegration(RuntimeIntegrationResult::REJECTED,nested.nestedResult);TEST_ASSERT_EQUAL_UINT32(1U,nested.calls);TEST_ASSERT_EQUAL_UINT32(1U,f.sink.sendCalls);TEST_ASSERT_FALSE(binding.isDispatching());}

void test_dispatch_binding_ignored_event_does_not_block_next_event()
{EventQueue queue;EventDispatcher dispatcher(queue);NotificationFixture f(true,10000U);EventToNotificationBridge bridge(f.adapter);EventToNotificationDispatchBinding binding(queue,dispatcher,bridge);binding.begin();Event ignored=makeEvent(EventType::NODE_ONLINE,EventSeverity::INFO,1U),valid=makeEvent(EventType::NODE_OFFLINE,EventSeverity::ERROR,2U);ignored.timestampMs=1000U;valid.timestampMs=1100U;queue.publish(ignored);queue.publish(valid);assertIntegration(RuntimeIntegrationResult::SUCCESS,binding.dispatchEvents(5000U));TEST_ASSERT_TRUE(queue.empty());TEST_ASSERT_EQUAL_UINT32(1U,f.sink.sendCalls);TEST_ASSERT_EQUAL_UINT32(1U,f.adapter.ignoredCount());TEST_ASSERT_EQUAL_UINT32(1U,f.adapter.forwardedCount());TEST_ASSERT_EQUAL_UINT32(2U,f.adapter.nextNotificationId());}

void test_main_controller_event_port_is_single_dispatch_owner()
{EventQueue queue;EventDispatcher dispatcher(queue);NotificationFixture f(true,10000U);EventToNotificationBridge bridge(f.adapter);EventToNotificationDispatchBinding binding(queue,dispatcher,bridge);EventRuntimeControllerPort port(binding);MainControllerDependencies dependencies;TEST_ASSERT_TRUE(dependencies.set(port));TEST_ASSERT_TRUE(dependencies.require(MainControllerComponent::EVENT));MainController controller(dependencies);TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(MainControllerComponent::EVENT),static_cast<uint8_t>(port.component()));TEST_ASSERT_TRUE(port.critical());TEST_ASSERT_TRUE(port.hasBegin());TEST_ASSERT_TRUE(port.hasUpdate());TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(MainControllerResult::SUCCESS),static_cast<uint8_t>(controller.begin(10U)));TEST_ASSERT_EQUAL_UINT32(1U,dispatcher.handlerCount());TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(MainControllerResult::SUCCESS),static_cast<uint8_t>(controller.begin(11U)));TEST_ASSERT_EQUAL_UINT32(1U,dispatcher.handlerCount());TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(MainControllerResult::NO_CHANGE),static_cast<uint8_t>(controller.update(4000U)));Event event=makeEvent();event.timestampMs=1000U;queue.publish(event);const uint32_t before=f.adapter.forwardedCount();TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(MainControllerResult::SUCCESS),static_cast<uint8_t>(controller.update(5000U)));TEST_ASSERT_TRUE(queue.empty());TEST_ASSERT_EQUAL_UINT32(1U,f.sink.sendCalls);TEST_ASSERT_EQUAL_UINT32(before+1U,f.adapter.forwardedCount());TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(MainControllerResult::NO_CHANGE),static_cast<uint8_t>(controller.update(5001U)));TEST_ASSERT_TRUE(queue.empty());TEST_ASSERT_EQUAL_UINT32(1U,dispatcher.handlerCount());TEST_ASSERT_EQUAL_UINT32(1U,f.sink.sendCalls);TEST_ASSERT_EQUAL_UINT32(before+1U,f.adapter.forwardedCount());FailingHandler failing;TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(EventHandlerRegistrationResult::SUCCESS),static_cast<uint8_t>(dispatcher.addHandler(failing)));event.id=2U;queue.publish(event);TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(MainControllerResult::COMPONENT_FAILED),static_cast<uint8_t>(controller.update(5000U)));TEST_ASSERT_EQUAL_UINT32(1U,failing.calls);TEST_ASSERT_EQUAL_UINT32(2U,f.sink.sendCalls);}

void test_main_controller_event_port_defers_events_published_during_dispatch()
{EventQueue queue;EventDispatcher dispatcher(queue);NotificationFixture f(true,10000U);EventToNotificationBridge bridge(f.adapter);EventToNotificationDispatchBinding binding(queue,dispatcher,bridge);EventRuntimeControllerPort port(binding);MainControllerDependencies dependencies;dependencies.set(port);dependencies.require(MainControllerComponent::EVENT);MainController controller(dependencies);controller.begin(0U);Event a=makeEvent(EventType::NODE_OFFLINE,EventSeverity::ERROR,1U),b=makeEvent(EventType::NODE_OFFLINE,EventSeverity::ERROR,2U);a.timestampMs=1000U;b.timestampMs=1100U;PublishingHandler publisher(queue,b);dispatcher.addHandler(publisher);queue.publish(a);TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(MainControllerResult::SUCCESS),static_cast<uint8_t>(controller.update(5000U)));TEST_ASSERT_EQUAL_UINT32(1U,f.sink.sendCalls);TEST_ASSERT_EQUAL_UINT32(1U,queue.size());TEST_ASSERT_EQUAL_UINT32(2U,queue.peek()->id);TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(EventPublishResult::SUCCESS),static_cast<uint8_t>(publisher.publishResult));TEST_ASSERT_EQUAL_UINT8(static_cast<uint8_t>(MainControllerResult::SUCCESS),static_cast<uint8_t>(controller.update(5000U)));TEST_ASSERT_EQUAL_UINT32(2U,f.sink.sendCalls);TEST_ASSERT_TRUE(queue.empty());TEST_ASSERT_EQUAL_UINT32(2U,publisher.calls);}

void test_dispatch_result_priority_is_order_independent_and_fail_closed()
{assertIntegration(RuntimeIntegrationResult::RETRY_LATER,EventToNotificationDispatchBindingTestAccess::combine(RuntimeIntegrationResult::RETRY_LATER,RuntimeIntegrationResult::NO_CHANGE));assertIntegration(RuntimeIntegrationResult::RETRY_LATER,EventToNotificationDispatchBindingTestAccess::combine(RuntimeIntegrationResult::NO_CHANGE,RuntimeIntegrationResult::RETRY_LATER));assertIntegration(RuntimeIntegrationResult::IN_PROGRESS,EventToNotificationDispatchBindingTestAccess::combine(RuntimeIntegrationResult::IN_PROGRESS,RuntimeIntegrationResult::IGNORED));assertIntegration(RuntimeIntegrationResult::IN_PROGRESS,EventToNotificationDispatchBindingTestAccess::combine(RuntimeIntegrationResult::IGNORED,RuntimeIntegrationResult::IN_PROGRESS));assertIntegration(RuntimeIntegrationResult::RETRY_LATER,EventToNotificationDispatchBindingTestAccess::combine(RuntimeIntegrationResult::SUCCESS,RuntimeIntegrationResult::RETRY_LATER));assertIntegration(RuntimeIntegrationResult::RETRY_LATER,EventToNotificationDispatchBindingTestAccess::combine(RuntimeIntegrationResult::RETRY_LATER,RuntimeIntegrationResult::SUCCESS));assertIntegration(RuntimeIntegrationResult::FAILED,EventToNotificationDispatchBindingTestAccess::combine(RuntimeIntegrationResult::FAILED,RuntimeIntegrationResult::SUCCESS));assertIntegration(RuntimeIntegrationResult::FAILED,EventToNotificationDispatchBindingTestAccess::combine(RuntimeIntegrationResult::SUCCESS,RuntimeIntegrationResult::FAILED));assertIntegration(RuntimeIntegrationResult::INTERNAL_ERROR,EventToNotificationDispatchBindingTestAccess::combine(RuntimeIntegrationResult::INTERNAL_ERROR,RuntimeIntegrationResult::FAILED));assertIntegration(RuntimeIntegrationResult::INTERNAL_ERROR,EventToNotificationDispatchBindingTestAccess::combine(RuntimeIntegrationResult::FAILED,RuntimeIntegrationResult::INTERNAL_ERROR));assertIntegration(RuntimeIntegrationResult::RETRY_LATER,EventToNotificationDispatchBindingTestAccess::combineThree(RuntimeIntegrationResult::NO_CHANGE,RuntimeIntegrationResult::SUCCESS,RuntimeIntegrationResult::RETRY_LATER));assertIntegration(RuntimeIntegrationResult::FAILED,EventToNotificationDispatchBindingTestAccess::combineThree(RuntimeIntegrationResult::SUCCESS,RuntimeIntegrationResult::FAILED,RuntimeIntegrationResult::NO_CHANGE));assertIntegration(RuntimeIntegrationResult::IN_PROGRESS,EventToNotificationDispatchBindingTestAccess::combineThree(RuntimeIntegrationResult::IGNORED,RuntimeIntegrationResult::SUCCESS,RuntimeIntegrationResult::IN_PROGRESS));assertIntegration(RuntimeIntegrationResult::INTERNAL_ERROR,EventToNotificationDispatchBindingTestAccess::combine(static_cast<RuntimeIntegrationResult>(255U),RuntimeIntegrationResult::SUCCESS));assertIntegration(RuntimeIntegrationResult::INTERNAL_ERROR,EventToNotificationDispatchBindingTestAccess::combine(RuntimeIntegrationResult::SUCCESS,static_cast<RuntimeIntegrationResult>(255U)));TEST_ASSERT_TRUE(EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::INTERNAL_ERROR)>EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::FAILED));TEST_ASSERT_TRUE(EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::FAILED)>EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::REJECTED));TEST_ASSERT_TRUE(EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::REJECTED)>EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::RETRY_LATER));TEST_ASSERT_TRUE(EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::RETRY_LATER)>EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::IN_PROGRESS));TEST_ASSERT_TRUE(EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::IN_PROGRESS)>EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::ACCEPTED));TEST_ASSERT_TRUE(EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::ACCEPTED)>EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::SUCCESS));TEST_ASSERT_TRUE(EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::SUCCESS)>EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::IGNORED));TEST_ASSERT_TRUE(EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::IGNORED)>EventToNotificationDispatchBindingTestAccess::priority(RuntimeIntegrationResult::NO_CHANGE));}

